      hu: ["Fontos vasúti és adminisztratív központ", "Gazdag kulturális és politikai történelemmel rendelkezik", "Itt található a Lulua-folyó egyik fontos átkelője"],
      ro: ["Fostul nume: Luluabourg", "Oraș universitar major", "Hub pentru rețeaua feroviară"],
